mapper.select:
SELECT MIN(started_at) AS first_started_at, MAX(ended_at) AS last_ended_at
FROM time_log
WHERE workspace_id = #{workspaceId} AND task_id = #{taskId}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
  AND ended_at IS NOT NULL AND started_at >= #{from}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId}
  AND ended_at IS NOT NULL AND started_at >= #{from}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId}
  AND ended_at IS NOT NULL
  AND started_at >= #{from} AND started_at < #{to}

SELECT user_id AS user_id, SUM(minutes) AS total_minutes FROM time_log
WHERE workspace_id = #{workspaceId}
  AND ended_at IS NOT NULL
  AND started_at >= #{from} AND started_at < #{to}
GROUP BY user_id

SELECT id, task_id, workspace_id, user_id, started_at, ended_at, minutes
FROM time_log
WHERE workspace_id = #{workspaceId}
  AND started_at >= #{from} AND started_at < #{to}

SELECT COALESCE(SUM(minutes), 0) AS total_all,
       COALESCE(SUM(CASE WHEN started_at >= #{from}
          AND started_at < #{to}
         THEN minutes ELSE 0 END), 0) AS week_all,
       COALESCE(SUM(CASE WHEN user_id = #{userId} THEN minutes ELSE 0 END), 0) AS total_mine,
       COALESCE(SUM(CASE WHEN user_id = #{userId} AND started_at >= #{from}
          AND started_at < #{to}
         THEN minutes ELSE 0 END), 0) AS week_mine
FROM time_log
WHERE workspace_id = #{workspaceId} AND ended_at IS NOT NULL
